local FRAME_MS = 1000.0 / 60.0

local SCENES = {
    { start = 0,    len = 150,  drum = INTRO },
    { start = 150,  len = 240,  box = 0, text = 0 },
    { start = 390,  len = 440,  box = 0, text = 1, drum = SCENE_2 },
